package license

import "encoding/hex"

// MasterPublicKey is the ML-DSA-65 public key for this repo's KHEPRA license
// signing root (fingerprint KHEPRA-ROOT-025b17fb88457ef9). Generated via
// cmd/root-ceremony; the corresponding private key exists only as Shamir
// shards (3-of-5, see keys/root-ceremony/ — gitignored, not committed).
//
// This is a DIFFERENT root from the one pinned in PQC-Khepra-MCP's
// pkg/license/master_pubkey.go — the two repos carry parallel forks of this
// license package and each gets its own independent root of trust, so a
// compromised or rotated root in one product doesn't affect the other.
//
// ParseMCPLicense pins VerifySovereignLicense against this constant instead
// of trusting whatever SignerPublicKey a license happens to carry — without
// this, any self-signed KhepraLicense verifies against itself.
var MasterPublicKey = mustDecodeHex(
	"")

func mustDecodeHex(s string) []byte {
	b, err := hex.DecodeString(s)
	if err != nil {
		panic("license: invalid MasterPublicKey hex: " + err.Error())
	}
	return b
}
